  // See Eq 5 in CK Manual
  amrex::Real W = 0;
  amrex::Real sumC = 0;
  W += c[0] * 1.0080000000000000e+00;  // h
  W += c[1] * 2.0160000000000000e+00;  // h2
  W += c[2] * 1.5999000000000001e+01;  // o
