  W += c[17] * 2.7045999999999999e+01; // c2h3
  W += c[18] * 4.2036999999999999e+01; // ch2co
  W += c[19] * 4.1028999999999996e+01; // hcco
  W += c[20] * 4.4052999999999997e+01; // ch3cho
  W += c[21] * 4.0064999999999998e+01; // c3h4-a
  W += c[22] * 4.2081000000000003e+01; // c3h6
  W += c[23] * 5.4091999999999999e+01; // c4h6
  W += c[24] * 4.3088999999999999e+01; // nc3h7
  W += c[25] * 5.5099999999999994e+01; // c4h7
  W += c[26] * 5.6107999999999997e+01; // c4h8-1
  W += c[27] * 5.7072000000000003e+01; // ch3coch2
  W += c[28] * 5.8080000000000005e+01; // c2h5cho
  W += c[29] * 6.9126999999999995e+01; // c5h9
  W += c[30] * 7.0134999999999991e+01; // c5h10-1
  W += c[31] * 4.7033000000000001e+01; // ch3o2
  W += c[32] * 4.8040999999999997e+01; // ch3o2h
  W += c[33] * 5.5056000000000004e+01; // c2h3co
  W += c[34] * 5.6064000000000000e+01; // c2h3cho
  W += c[35] * 1.2111199999999999e+02; // c4h8ooh1-3o2
  W += c[36] * 8.9114000000000004e+01; // pc4h9o2
  W += c[37] * 4.1073000000000000e+01; // c3h5-a
  W += c[38] * 3.9057000000000002e+01; // c3h3
  W += c[39] * 1.0410499999999999e+02; // nc4ket13
  W += c[40] * 7.2106999999999999e+01; // nc3h7cho
  W += c[41] * 7.1098999999999990e+01; // c2h5coch2
  W += c[42] * 8.5125999999999991e+01; // nc3h7coch2
  W += c[43] * 8.6133999999999986e+01; // nc4h9cho
  W += c[44] * 8.5125999999999991e+01; // nc4h9co
  W += c[45] * 1.0020500000000000e+02; // nc7h16
  W += c[46] * 1.3119499999999999e+02; // c7h15o2-1
  W += c[47] * 1.3119499999999999e+02; // c7h15o2-2
  W += c[48] * 1.3119499999999999e+02; // c7h15o2-3
  W += c[49] * 1.3119499999999999e+02; // c7h15o2-4
