  XW += x[43] * 8.6133999999999986e+01; // nc4h9cho
  XW += x[44] * 8.5125999999999991e+01; // nc4h9co
  XW += x[45] * 1.0020500000000000e+02; // nc7h16
  XW += x[46] * 1.3119499999999999e+02; // c7h15o2-1
  XW += x[47] * 1.3119499999999999e+02; // c7h15o2-2
  XW += x[48] * 1.3119499999999999e+02; // c7h15o2-3
  XW += x[49] * 1.3119499999999999e+02; // c7h15o2-4
  XW += x[50] * 1.3119499999999999e+02; // c7h14ooh4-3
  XW += x[51] * 1.6319300000000001e+02; // c7h14ooh1-3o2
  XW += x[52] * 1.1418799999999999e+02; // c7h14o1-3
  XW += x[53] * 1.1418799999999999e+02; // c7h14o2-4
  XW += x[54] * 2.8013999999999999e+01; // n2
  // Now compute conversion
  amrex::Real XWinv = 1.0 / XW;
  y[0] = x[0] * 1.0080000000000000e+00 * XWinv;
  y[1] = x[1] * 2.0160000000000000e+00 * XWinv;
  y[2] = x[2] * 1.5999000000000001e+01 * XWinv;
