  y[10] = x[10] * 3.3006000000000000e+01 * XWinv;
  y[11] = x[11] * 3.4014000000000003e+01 * XWinv;
  y[12] = x[12] * 3.0026000000000000e+01 * XWinv;
  y[13] = x[13] * 3.0070000000000000e+01 * XWinv;
  y[14] = x[14] * 2.8053999999999998e+01 * XWinv;
