  y[23] = x[23] * 5.4091999999999999e+01 * XWinv;
  y[24] = x[24] * 4.3088999999999999e+01 * XWinv;
  y[25] = x[25] * 5.5099999999999994e+01 * XWinv;
  y[26] = x[26] * 5.6107999999999997e+01 * XWinv;
  y[27] = x[27] * 5.7072000000000003e+01 * XWinv;
