  CW += c[39] * 1.0410499999999999e+02; // nc4ket13
  CW += c[40] * 7.2106999999999999e+01; // nc3h7cho
  CW += c[41] * 7.1098999999999990e+01; // c2h5coch2
  CW += c[42] * 8.5125999999999991e+01; // nc3h7coch2
  CW += c[43] * 8.6133999999999986e+01; // nc4h9cho
  CW += c[44] * 8.5125999999999991e+01; // nc4h9co
  CW += c[45] * 1.0020500000000000e+02; // nc7h16
  CW += c[46] * 1.3119499999999999e+02; // c7h15o2-1
