  CW += c[49] * 1.3119499999999999e+02; // c7h15o2-4
  CW += c[50] * 1.3119499999999999e+02; // c7h14ooh4-3
  CW += c[51] * 1.6319300000000001e+02; // c7h14ooh1-3o2
